import { formatAdminURL, getSafeRedirect } from 'payload/shared';
/**
 * Applies the `payloadRedirect` cookie (Payload's `?redirect=` login param, saved by
 * `LoginButton`) to the post-login redirect URL.
 *
 * Payload sets `?redirect=` to the full admin path, e.g. `/admin/collections/posts`, or to just a
 * query string when login started at the admin root. Appending a path to the admin URL would
 * double the admin route (`/admin/admin/collections/posts`), so paths are resolved from the
 * origin instead. Unsafe values, including absolute URLs, are ignored.
 *
 * @example resolvePayloadRedirect('/admin/collections/posts', 'https://site/admin') // 'https://site/admin/collections/posts'
 * @example resolvePayloadRedirect('?embed=true', 'https://site/admin') // 'https://site/admin?embed=true'
 */ export function resolvePayloadRedirect(payloadRedirect, redirectURL) {
    if (payloadRedirect.startsWith('?')) {
        return redirectURL + payloadRedirect;
    }
    const path = getSafeRedirect({
        fallbackTo: '',
        redirectTo: payloadRedirect
    });
    if (!path) {
        return redirectURL;
    }
    // `adminRoute: '/'` adds no route segment, leaving the origin, any Next.js basePath, and `path`.
    return formatAdminURL({
        adminRoute: '/',
        path: path,
        serverURL: redirectURL
    });
}
